/** Creates up to {@link #MAX_BATCH_SIZE} links. Each item succeeds or is rejected on its own, in input order. */
public List<BatchItemResult> createBatch(List<CreateCommand> commands) {
    if (commands == null || commands.isEmpty()) {
        throw new InvalidRequest("at least one url is required");
    }
    if (commands.size() > MAX_BATCH_SIZE) {
        throw new InvalidRequest("at most " + MAX_BATCH_SIZE + " urls can be created in one request");
    }
    List<BatchItemResult> results = new ArrayList<>(commands.size());
    for (int i = 0; i < commands.size(); i++) {
        try {
            results.add(BatchItemResult.created(i, create(commands.get(i))));
        } catch (InvalidRequest | AliasTaken e) {
            results.add(BatchItemResult.rejected(i, e.getMessage()));
        }
    }
    return results;
}

